const LOGIN = "<!DOCTYPE html><html lang=\"uz\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"robots\" content=\"noindex,nofollow\"><title>Admin \u2014 kirish</title>\n<style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#0A0E0C;color:#E9EEEB;font:16px/1.5 system-ui,sans-serif;padding:20px;box-sizing:border-box}\nform{width:min(380px,100%);background:#111714;border:1px solid rgba(255,255,255,.1);border-radius:20px;padding:28px;display:grid;gap:14px}\nh1{margin:0 0 6px;font-size:22px}label{display:grid;gap:6px;font-size:14px;color:#98A49E}\ninput{font:inherit;padding:12px 14px;border-radius:10px;border:1px solid rgba(255,255,255,.15);background:#18201C;color:#E9EEEB}input:focus{outline:2px solid #3DDC97;border-color:transparent}\nbutton{font:inherit;font-weight:700;min-height:48px;border:0;border-radius:12px;background:#3DDC97;color:#04140C;cursor:pointer}button:disabled{opacity:.6}\n.err{color:#ff6b6b;min-height:20px;margin:0;font-size:14px}</style></head><body>\n<form id=\"f\"><h1>HTML Akademiya \u2014 admin</h1>\n<label>Login<input name=\"user\" autocomplete=\"username\" required></label>\n<label>Parol<input name=\"key\" type=\"password\" autocomplete=\"current-password\" required></label>\n<p class=\"err\" id=\"e\"></p><button>Kirish</button></form>\n<script>const f=document.getElementById(\"f\"),e=document.getElementById(\"e\");\nf.onsubmit=async ev=>{ev.preventDefault();e.textContent=\"\";f.querySelector(\"button\").disabled=true;\ntry{const r=await fetch(\"/api/admin-login\",{method:\"POST\",headers:{\"content-type\":\"application/json\"},body:JSON.stringify({user:f.user.value,key:f.key.value})});const j=await r.json().catch(()=>({}));\nif(r.ok){location.reload();return}e.textContent=j.error===\"locked\"?\"Ko'p xato urinish \u2014 15 daqiqadan keyin urinib ko'ring\":j.error===\"not configured\"?\"Vercel'da ADMIN_KEY qo'shilmagan\":\"Login yoki parol noto'g'ri\"+(j.left!=null?\" (qoldi: \"+j.left+\")\":\"\")}\ncatch{e.textContent=\"Tarmoq xatosi\"}f.querySelector(\"button\").disabled=false}</script></body></html>\n";
export default function handler(req, res) {
  res.setHeader("Cache-Control", "no-store");
  res.setHeader("content-type", "text/html; charset=utf-8");
  res.setHeader("X-Robots-Tag", "noindex");
  res.status(200).send(isAdmin(req) ? PANEL : LOGIN);
}
